mapper.select:
SELECT A.MDFM_ELMT_INPT_CNTE AS mdfmElmtInptCnte
FROM ODS.S_MRDDRECE A
WHERE A.MDRC_ID = ${mdrcId}
  AND A.MDRC_FOM_SEQ = ${mdrcFomSeq}
  AND A.MDFM_CPEM_ID = #{mdfmCpemId}
ORDER BY A.REC_VAL_SEQ

SELECT A.DCST_LDAT AS dcstLdat,
       A.INTG_IMG_FILE_PATH_NM AS intgImgFilePathNm
FROM ODS.S_MRDDRLFE A
WHERE A.MDRC_ID = ${mdrcId}
  AND A.MDRC_FOM_SEQ = ${mdrcFomSeq}
  AND A.MDFM_CPEM_ID = #{mdfmCpemId}
ORDER BY A.REC_VAL_SEQ
